import{_ as o,o as e,c as t,ag as n}from"./chunks/framework.gmyryY1Z.js";const g=JSON.parse('{"title":"アーキテクチャ進化の概要","description":"","frontmatter":{},"headers":[],"relativePath":"ja/evolution/index.md","filePath":"ja/evolution/index.md","lastUpdated":null}'),s={name:"ja/evolution/index.md"};function r(l,a,i,p,d,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="アーキテクチャ進化の概要" tabindex="-1">アーキテクチャ進化の概要 <a class="header-anchor" href="#アーキテクチャ進化の概要" aria-label="Permalink to &quot;アーキテクチャ進化の概要&quot;">​</a></h1><p>Fast Vue3 は <strong>Polyrepo（単一リポジトリ）</strong> から <strong>Monorepo（マルチパッケージリポジトリ）</strong> への完全なアーキテクチャ進化を経験しました。</p><h2 id="タイムライン" tabindex="-1">タイムライン <a class="header-anchor" href="#タイムライン" aria-label="Permalink to &quot;タイムライン&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2022 ～ 2024         2025 Q1              2025 Q2 ～ 現在</span></span>
<span class="line"><span>────────────        ────────────         ────────────────</span></span>
<span class="line"><span> Polyrepo フェーズ    アーカイブフェーズ    Monorepo フェーズ</span></span>
<span class="line"><span> 単一アプリ           polyrepo ブランチ     main ブランチ再構築</span></span>
<span class="line"><span> 標準化・最適化        履歴保存              マルチアプリプラットフォーム</span></span></code></pre></div><h2 id="_2-つのアーキテクチャ" tabindex="-1">2 つのアーキテクチャ <a class="header-anchor" href="#_2-つのアーキテクチャ" aria-label="Permalink to &quot;2 つのアーキテクチャ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ブランチ</th><th>アーキテクチャ</th><th>説明</th></tr></thead><tbody><tr><td><code>polyrepo</code></td><td>Polyrepo</td><td>旧アーキテクチャ（アーカイブ済み）</td></tr><tr><td><code>main</code></td><td>Monorepo</td><td>新アーキテクチャ（継続的に進化）</td></tr></tbody></table><h2 id="なぜ移行したか" tabindex="-1">なぜ移行したか <a class="header-anchor" href="#なぜ移行したか" aria-label="Permalink to &quot;なぜ移行したか&quot;">​</a></h2><p>Polyrepo の主要な問題点：</p><ol><li><strong>バージョン分散</strong> — 依存バージョンが単一の <code>package.json</code> に混在</li><li><strong>コード再利用不可</strong> — 複数 UI 対応にはプロジェクト全体のコピーが必要</li><li><strong>設定の重複</strong> — ESLint・TypeScript・Vite 設定を毎回書き直し</li><li><strong>パッケージ境界なし</strong> — <code>src/</code> 下にすべてが混在</li><li><strong>スケーラビリティ不足</strong> — 新技術スタック追加にはフォークが必要</li></ol><p>Monorepo が解決する問題：</p><ul><li><strong>バージョン統一管理</strong> — pnpm workspace catalog</li><li><strong>インフラ共有</strong> — <code>packages/*</code> を一度書いて全アプリで再利用</li><li><strong>スケーラビリティ</strong> — <code>apps/</code> に追加するだけで新 UI エコシステムに対応</li><li><strong>明確な境界</strong> — 各パッケージが単一の責任を持つ</li></ul><h2 id="このセクションの内容" tabindex="-1">このセクションの内容 <a class="header-anchor" href="#このセクションの内容" aria-label="Permalink to &quot;このセクションの内容&quot;">​</a></h2><ul><li><a href="./polyrepo">Polyrepo 旧アーキテクチャ</a> — 元の構造分析・技術的負債・最適化内容</li><li><a href="./monorepo">Monorepo 新アーキテクチャ</a> — 新アーキテクチャ設計・パッケージ分割戦略</li><li><a href="./comparison">アーキテクチャ比較</a> — 2 つのアーキテクチャの比較分析</li></ul>`,13)])])}const u=o(s,[["render",r]]);export{g as __pageData,u as default};
